begin;
create table public.budget_limits(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,company_id uuid not null,cost_center_id uuid,category_id uuid,competence_month date not null,limit_amount numeric(14,2) not null check(limit_amount>=0),warning_percent numeric(5,2) not null default 80 check(warning_percent>=0 and warning_percent<=100),notes text,status text not null default 'active' check(status in('active','inactive')),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint budget_limits_month_ck check(competence_month=date_trunc('month',competence_month)::date),constraint budget_limits_company_fk foreign key(tenant_id,company_id) references public.companies(tenant_id,id) on delete restrict,constraint budget_limits_cost_center_fk foreign key(tenant_id,company_id,cost_center_id) references public.cost_centers(tenant_id,company_id,id) on delete restrict,constraint budget_limits_category_fk foreign key(tenant_id,company_id,category_id) references public.financial_categories(tenant_id,company_id,id) on delete restrict);
create unique index budget_limits_scope_uidx on public.budget_limits(tenant_id,company_id,coalesce(cost_center_id,'00000000-0000-0000-0000-000000000000'::uuid),coalesce(category_id,'00000000-0000-0000-0000-000000000000'::uuid),competence_month) where status='active';
create index budget_limits_company_month_idx on public.budget_limits(tenant_id,company_id,competence_month);
alter table public.budget_limits enable row level security;
create policy budget_limits_select on public.budget_limits for select to authenticated using(app_private.can_access_company(tenant_id,company_id));
create policy budget_limits_insert on public.budget_limits for insert to authenticated with check(app_private.can_access_company(tenant_id,company_id));
create policy budget_limits_update on public.budget_limits for update to authenticated using(app_private.can_access_company(tenant_id,company_id)) with check(app_private.can_access_company(tenant_id,company_id));
create policy budget_limits_delete on public.budget_limits for delete to authenticated using(app_private.can_access_company(tenant_id,company_id));
create view public.budget_limit_control with(security_invoker=true) as select l.id limit_id,l.tenant_id,l.company_id,l.cost_center_id,l.category_id,l.competence_month,l.limit_amount,l.warning_percent,coalesce(b.actual_expense,0)::numeric(18,2) consumed_amount,(l.limit_amount-coalesce(b.actual_expense,0))::numeric(18,2) remaining_amount,case when l.limit_amount>0 then round(coalesce(b.actual_expense,0)*100/l.limit_amount,2) else 0 end consumed_percent,case when coalesce(b.actual_expense,0)>l.limit_amount then 'exceeded' when l.limit_amount>0 and coalesce(b.actual_expense,0)*100/l.limit_amount>=l.warning_percent then 'warning' else 'ok' end limit_status from public.budget_limits l left join public.budget_monthly_control b on b.tenant_id=l.tenant_id and b.company_id=l.company_id and b.cost_center_id is not distinct from l.cost_center_id and b.category_id is not distinct from l.category_id and b.competence_month=l.competence_month where l.status='active';
commit;
